160:    /**
161:     * Returns the current monitoring state of the client.
162:     */
163:    @RequiresPermission(Car.PERMISSION_VMS_SUBSCRIBER)
164:    @AddedInOrBefore(majorVersion = 33)
165:    public boolean isMonitoringEnabled() {
