213:        if (DBG) Log.d(TAG, "Unregistering provider");
214:        try {
215:            setProviderOfferings(providerId, Collections.emptySet());
216:        } catch (IllegalArgumentException e) {
217:            Log.e(TAG, "While unregistering provider " + providerId, e);
218:        }
