295:                mClientToken, mClientCallback, mLegacyClient);
296:        synchronized (mLock) {
297:            mAvailableLayers = registrationInfo.getAvailableLayers();
298:            mSubscriptionState = registrationInfo.getSubscriptionState();
299:        }
300:    }
