152:     *
153:     * @param offering layers being offered for subscription by the publisher
154:     * @throws IllegalStateException if publisher services are not available
155:     */
156:    @AddedInOrBefore(majorVersion = 33)
157:    public final void setLayersOffering(@NonNull VmsLayersOffering offering) {
158:        getVmsClient().setProviderOfferings(offering.getPublisherId(), offering.getDependencies());
159:    }
160:
161:    /**
162:     * Acquires a publisher ID for a serialized publisher description.
163:     *
164:     * Multiple calls to this method with the same information will return the same publisher ID.
165:     *
166:     * @param publisherInfo serialized publisher description information, in a vendor-specific
167:     *                      format
168:     * @return a publisher ID for the given publisher description
169:     * @throws IllegalStateException if publisher services are not available
170:     */
171:    @AddedInOrBefore(majorVersion = 33)
172:    public final int getPublisherId(byte[] publisherInfo) {
173:        return getVmsClient().registerProvider(publisherInfo);
174:    }
175:
176:    /**
177:     * Gets the state of layer subscriptions.
178:     *
179:     * @return state of layer subscriptions
180:     * @throws IllegalStateException if publisher services are not available
181:     */
182:    @AddedInOrBefore(majorVersion = 33)
183:    public final VmsSubscriptionState getSubscriptions() {
184:        return getVmsClient().getSubscriptionState();
185:    }
186:
187:    private VmsClient getVmsClient() {
188:        synchronized (mLock) {
189:            if (mClient == null) {
190:                throw new IllegalStateException("VMS client connection is not ready");
191:            }
192:            return mClient;
193:        }
194:    }
195:
196:    private class PublisherClientCallback implements VmsClientCallback {
197:        @Override
198:        public void onClientConnected(VmsClient client) {
199:            synchronized (mLock) {
200:                mClient = client;
201:            }
202:            onVmsPublisherServiceReady();
203:        }
204:
205:        @Override
206:        public void onSubscriptionStateChanged(VmsSubscriptionState subscriptionState) {
207:            onVmsSubscriptionChange(subscriptionState);
208:        }
