210:        @Override
211:        public void onLayerAvailabilityChanged(VmsAvailableLayers availableLayers) {
212:            // Ignored
213:        }
214:
215:        @Override
216:        public void onPacketReceived(int providerId, VmsLayer layer, byte[] packet) {
217:            // Does not subscribe to packets
218:        }
219:    }
220:}

