43:/**
44: * Class for tracking Vehicle Map Service client information, offerings, and subscriptions.
45: */
46:final class VmsClientInfo {
47:    private final int mUid;
48:    private final String mPackageName;
49:    private final IVmsClientCallback mCallback;
50:    private final boolean mLegacyClient;
51:    private final IBinder.DeathRecipient mDeathRecipient;
