59:    private final SparseArray<Set<VmsLayer>> mPotentialOfferings = new SparseArray<>();
60:    @GuardedBy("mLock")
61:    private Set<VmsLayer> mLayerSubscriptions = Collections.emptySet();
62:    @GuardedBy("mLock")
63:    private Map<VmsLayer, Set<Integer>> mLayerAndProviderSubscriptions = Collections.emptyMap();
64:    @GuardedBy("mLock")
65:    private boolean mMonitoringEnabled;
66:
67:    VmsClientInfo(int uid, String packageName, IVmsClientCallback callback, boolean legacyClient,
68:            IBinder.DeathRecipient deathRecipient) {
69:        mUid = uid;
70:        mPackageName = packageName;
71:        mCallback = callback;
