78:    }
79:
80:    String getPackageName() {
81:        return mPackageName;
82:    }
83:
84:    IVmsClientCallback getCallback() {
85:        return mCallback;
86:    }
87:
88:    boolean isLegacyClient() {
89:        return mLegacyClient;
90:    }
91:
92:    IBinder.DeathRecipient getDeathRecipient() {
93:        return mDeathRecipient;
94:    }
95:
96:    void addProviderId(int providerId) {
97:        synchronized (mLock) {
98:            mProviderIds.put(providerId, true);
99:        }
100:    }
101:
102:    boolean hasProviderId(int providerId) {
103:        synchronized (mLock) {
104:            return mProviderIds.get(providerId);
105:        }
106:    }
107:
108:    boolean setProviderOfferings(int providerId, Collection<VmsLayerDependency> offerings) {
109:        synchronized (mLock) {
110:            Set<VmsLayerDependency> providerOfferings = mOfferings.get(providerId);
111:
112:            // If the offerings are unchanged, do nothing
113:            if (providerOfferings != null
114:                    && providerOfferings.size() == offerings.size()
115:                    && providerOfferings.containsAll(offerings)) {
116:                return false;
117:            }
118:
119:            // Otherwise, update the offerings and return true
120:            mOfferings.put(providerId, new ArraySet<>(offerings));
121:            mPotentialOfferings.put(providerId, offerings.stream()
122:                    .map(VmsLayerDependency::getLayer)
