131:            for (int i = 0; i < mOfferings.size(); i++) {
132:                int providerId = mOfferings.keyAt(i);
133:                Set<VmsLayerDependency> providerOfferings = mOfferings.valueAt(i);
134:                result.add(new VmsLayersOffering(new ArraySet<>(providerOfferings), providerId));
135:            }
136:        }
137:        return result;
138:    }
