153:                    .filter(associatedLayer -> !associatedLayer.getProviderIds().isEmpty())
154:                    .collect(Collectors.toMap(
155:                            VmsAssociatedLayer::getVmsLayer,
156:                            associatedLayer -> new ArraySet<>(associatedLayer.getProviderIds())));
157:        }
158:    }
159:
160:    Set<VmsLayer> getLayerSubscriptions() {
161:        synchronized (mLock) {
162:            return new ArraySet<>(mLayerSubscriptions);
163:        }
164:    }
165:
166:    Map<VmsLayer, Set<Integer>> getLayerAndProviderSubscriptions() {
167:        synchronized (mLock) {
168:            return deepCopy(mLayerAndProviderSubscriptions);
