170:    }
171:
172:    void setMonitoringEnabled(boolean enabled) {
173:        synchronized (mLock) {
174:            mMonitoringEnabled = enabled;
175:        }
176:    }
177:
178:    boolean isSubscribed(int providerId, VmsLayer layer) {
179:        synchronized (mLock) {
180:            return mMonitoringEnabled
181:                    || mLayerSubscriptions.contains(layer)
182:                    || mLayerAndProviderSubscriptions.getOrDefault(layer, Collections.emptySet())
183:                            .contains(providerId);
184:        }
185:    }
