305:            if (result.status != StatusCode.OK) {
306:                throw new ServiceSpecificException(
307:                        result.status, "failed to set value: " + request.value);
308:            }
309:        } catch (InterruptedException e) {
310:            Thread.currentThread().interrupt(); // Restore the interrupted status
311:            throw new ServiceSpecificException(StatusCode.INTERNAL_ERROR,
312:                    "thread interrupted, possibly exiting the thread");
313:        } catch (ExecutionException e) {
314:            throw new ServiceSpecificException(StatusCode.INTERNAL_ERROR,
315:                    "failed to resolve SetValue future, error: " + e);
316:        } catch (TimeoutException e) {
317:            synchronized (mLock) {
318:                mPendingSetValueRequests.remove(requestId);
319:            }
