18:
19:import static java.util.concurrent.Executors.newSingleThreadScheduledExecutor;
20:
21:import android.os.SystemClock;
22:
23:import com.android.internal.annotations.GuardedBy;
24:
25:import java.util.concurrent.ScheduledExecutorService;
26:import java.util.concurrent.TimeUnit;
27:
28:/**
29: * Interface that abstracts time operations
30: */
31:public interface TimeInterface {
32:    public static final boolean INCLUDE_DEEP_SLEEP_TIME = true;
33:    public static final boolean EXCLUDE_DEEP_SLEEP_TIME = false;
34:
35:    default long getUptime() {
36:        return getUptime(EXCLUDE_DEEP_SLEEP_TIME);
37:    }
38:    default long getUptime(boolean includeDeepSleepTime) {
39:        return includeDeepSleepTime ?
40:            SystemClock.elapsedRealtime() :
41:            SystemClock.uptimeMillis();
42:    }
43:
44:    void scheduleAction(Runnable r, long delayMs);
45:    void cancelAllActions();
46:
47:    class DefaultImpl implements TimeInterface {
48:        private final Object mLock = new Object();
49:
50:        @GuardedBy("mLock")
51:        private ScheduledExecutorService mExecutor;
52:
53:        @Override
54:        public void scheduleAction(Runnable r, long delayMs) {
55:            ScheduledExecutorService executor;
56:            synchronized (mLock) {
57:                executor = mExecutor;
58:                if (executor == null) {
59:                    executor = newSingleThreadScheduledExecutor();
60:                    mExecutor = executor;
61:                }
62:            }
63:            executor.scheduleAtFixedRate(r, delayMs, delayMs, TimeUnit.MILLISECONDS);
64:        }
65:
66:        @Override
67:        public void cancelAllActions() {
68:            ScheduledExecutorService executor;
