335:        }
336:        CarServiceUtils.assertPermission(mContext, mHal.getReadPermission(propId));
337:        if (listener == null) {
338:            Slogf.e(TAG, "unregisterListener: Listener is null.");
339:            throw new IllegalArgumentException("Listener is null");
