399:    private void unregisterListenerBinderForProps(List<Integer> propIds, IBinder listenerBinder) {
400:        synchronized (mLock) {
401:            for (int i = 0; i < propIds.size(); i++) {
402:                int propId = propIds.get(i);
403:                unregisterListenerBinderLocked(propId, listenerBinder);
404:            }
405:        }
406:    }
