460:    private static boolean checkAndUpdateGrantedPermissionSet(Context context,
461:            Set<String> grantedPermissions, @Nullable String permission) {
462:        if (permission != null && (grantedPermissions.contains(permission)
463:                || CarServiceUtils.hasPermission(context, permission))) {
464:            grantedPermissions.add(permission);
465:            return true;
466:        }
467:        return false;
468:    }
