618:    }
619:
620:    // Implement PropertyHalListener interface
621:    @Override
622:    public void onPropertyChange(List<CarPropertyEvent> events) {
623:        Map<Client, List<CarPropertyEvent>> eventsToDispatch = new ArrayMap<>();
624:        synchronized (mLock) {
625:            for (int i = 0; i < events.size(); i++) {
626:                CarPropertyEvent event = events.get(i);
627:                int propId = event.getCarPropertyValue().getPropertyId();
628:                List<Client> clients = mPropIdClientMap.get(propId);
629:                if (clients == null) {
630:                    Slogf.e(TAG, "onPropertyChange: no listener registered for propId=0x%s",
631:                            toHexString(propId));
632:                    continue;
633:                }
634:
635:                for (int j = 0; j < clients.size(); j++) {
636:                    Client c = clients.get(j);
637:                    List<CarPropertyEvent> p = eventsToDispatch.get(c);
638:                    if (p == null) {
639:                        // Initialize the linked list for the listener
640:                        p = new ArrayList<CarPropertyEvent>();
641:                        eventsToDispatch.put(c, p);
642:                    }
643:                    p.add(event);
644:                }
645:            }
646:        }
647:
648:        // Parse the dispatch list to send events. We must call the callback outside the
649:        // scoped lock since the callback might call some function in CarPropertyService
650:        // which might cause dead-lock.
651:        // In rare cases, if this specific client is unregistered after the lock but before
652:        // the callback, we would call callback on an unregistered client which should be ok because
653:        // 'onEvent' is an async oneway callback that might be delivered after unregistration
654:        // anyway.
655:        for (Client client : eventsToDispatch.keySet()) {
656:            try {
657:                client.onEvent(eventsToDispatch.get(client));
658:            } catch (RemoteException ex) {
659:                // If we cannot send a record, its likely the connection snapped. Let binder
660:                // death handle the situation.
661:                Slogf.e(TAG, "onEvent calling failed: " + ex);
662:            }
663:        }
664:    }
665:
666:    @Override
667:    public void onPropertySetError(int property, int areaId, int errorCode) {
668:        Client lastOperatedClient = null;
669:        synchronized (mLock) {
670:            if (mSetOperationClientMap.get(property) != null
671:                    && mSetOperationClientMap.get(property).get(areaId) != null) {
672:                lastOperatedClient = mSetOperationClientMap.get(property).get(areaId);
673:            } else {
674:                Slogf.e(TAG, "Can not find the client changed propertyId: 0x"
675:                        + toHexString(property) + " in areaId: 0x" + toHexString(areaId));
676:            }
677:
678:        }
679:        if (lastOperatedClient != null) {
680:            dispatchToLastClient(property, areaId, errorCode, lastOperatedClient);
681:        }
682:    }
683:
684:    private void dispatchToLastClient(int property, int areaId, int errorCode,
685:            Client lastOperatedClient) {
686:        try {
687:            List<CarPropertyEvent> eventList = new ArrayList<>();
688:            eventList.add(
689:                    CarPropertyEvent.createErrorEventWithErrorCode(property, areaId,
690:                            errorCode));
691:            lastOperatedClient.onEvent(eventList);
692:        } catch (RemoteException ex) {
693:            Slogf.e(TAG, "onEvent calling failed: " + ex);
694:        }
695:    }
696:}
