3251:    private void registerClient(IBinder token, IVmsClientCallback callback) {
3252:        registerClient(token, callback, false);
3253:    }
3254:
3255:    private VmsRegistrationInfo registerClient(IBinder token, IVmsClientCallback callback,
3256:            boolean legacyClient) {
3257:        VmsRegistrationInfo registrationInfo =
3258:                mBrokerService.registerClient(token, callback, legacyClient);
3259:
3260:        IBinder callbackBinder = callback.asBinder();
3261:        try {
3262:            if (!mDeathRecipients.containsKey(token)) {
3263:                ArgumentCaptor<IBinder.DeathRecipient> deathRecipientCaptor =
3264:                        ArgumentCaptor.forClass(IBinder.DeathRecipient.class);
3265:                verify(callbackBinder).linkToDeath(deathRecipientCaptor.capture(), eq(0));
3266:                mDeathRecipients.put(token,
3267:                        Pair.create(callbackBinder, deathRecipientCaptor.getValue()));
3268:            } else {
3269:                verify(callbackBinder, never()).linkToDeath(any(), anyInt());
3270:            }
3271:        } catch (RemoteException e) {
3272:            e.rethrowAsRuntimeException();
3273:        }
3274:
3275:        return registrationInfo;
3276:    }
3277:
3278:    private void unregisterClient(IBinder token) {
3279:        mBrokerService.unregisterClient(token);
3280:
3281:        Pair<IBinder, IBinder.DeathRecipient> deathRecipientPair = mDeathRecipients.get(token);
3282:        assertThat(deathRecipientPair).isNotNull();
3283:        verify(deathRecipientPair.first).unlinkToDeath(same(deathRecipientPair.second), eq(0));
3284:    }
3285:
3286:    private void disconnectClient(IBinder token) {
3287:        Pair<IBinder, IBinder.DeathRecipient> deathRecipientPair = mDeathRecipients.get(token);
3288:        assertThat(deathRecipientPair).isNotNull();
3289:
3290:        deathRecipientPair.second.binderDied();
3291:        verify(deathRecipientPair.first).unlinkToDeath(same(deathRecipientPair.second), eq(0));
3292:    }
